from __future__ import annotations

"""Top-level calendar API: build an event, list its occurrences in a zone."""

from exdate_filter import apply_exdates, describe_exclusions
from occurrence_expander import expand
from recurrence_models import (
    Occurrence,
    RecurringEvent,
    build_event,
    parse_exdates,
    parse_rrule,
)
from timezone_rules import ExplicitDstZone, WallTime, build_eastern_2021
from wall_clock import resolve_wall_to_instant


class CalendarService:
    """Expand recurring events against a single named zone."""

    def __init__(self, zone: ExplicitDstZone | None = None) -> None:
        self._zone = zone if zone is not None else build_eastern_2021()
        self._events: dict[str, RecurringEvent] = {}

    @property
    def zone(self) -> ExplicitDstZone:
        return self._zone

    def add_event(self, event: RecurringEvent) -> RecurringEvent:
        self._events[event.event_id] = event
        return event

    def add_from_ical(
        self,
        *,
        event_id: str,
        dtstart: WallTime,
        rrule: str,
        exdate: str = "",
        summary: str = "",
    ) -> RecurringEvent:
        """Build and register an event from compact iCal-style fields."""

        rule = parse_rrule(rrule, until_resolver=self._resolve_until)
        exdates = parse_exdates(exdate)
        event = build_event(
            event_id=event_id,
            tzid=self._zone.name,
            dtstart=dtstart,
            rule=rule,
            summary=summary,
            exdates=exdates,
        )
        return self.add_event(event)

    def _resolve_until(self, wall: WallTime) -> int:
        return resolve_wall_to_instant(self._zone, wall)

    def get_event(self, event_id: str) -> RecurringEvent:
        if event_id not in self._events:
            raise KeyError(f"unknown event {event_id}")
        return self._events[event_id]

    def occurrences(self, event_id: str) -> list[Occurrence]:
        """Final occurrences for an event: expanded, with EXDATEs removed."""

        event = self.get_event(event_id)
        return apply_exdates(self._zone, event)

    def raw_occurrences(self, event_id: str) -> list[Occurrence]:
        """Occurrences before EXDATE filtering."""

        return expand(self._zone, self.get_event(event_id))

    def local_clocks(self, event_id: str) -> list[tuple[int, int, int]]:
        return [o.clock() for o in self.occurrences(event_id)]

    def local_dates(self, event_id: str) -> list[tuple[int, int, int]]:
        return [o.date_tuple() for o in self.occurrences(event_id)]

    def instants(self, event_id: str) -> list[int]:
        return [o.instant for o in self.occurrences(event_id)]

    def occurrence_count(self, event_id: str) -> int:
        return len(self.occurrences(event_id))

    def keeps_local_clock(self, event_id: str) -> bool:
        """Whether every occurrence reads the same wall clock as DTSTART."""

        event = self.get_event(event_id)
        target = (event.dtstart.hour, event.dtstart.minute, event.dtstart.second)
        return all(o.clock() == target for o in self.occurrences(event_id))

    def exclusion_report(self, event_id: str) -> dict[str, object]:
        return describe_exclusions(self._zone, self.get_event(event_id))

    def summarize(self, event_id: str) -> dict[str, object]:
        event = self.get_event(event_id)
        occ = self.occurrences(event_id)
        return {
            "event_id": event.event_id,
            "tzid": event.tzid,
            "freq": event.rule.freq,
            "count": len(occ),
            "first_wall": str(occ[0].local_wall) if occ else None,
            "last_wall": str(occ[-1].local_wall) if occ else None,
        }

    def event_ids(self) -> list[str]:
        return list(self._events)


def build_service() -> CalendarService:
    return CalendarService(build_eastern_2021())

