from __future__ import annotations

"""Remove EXDATE exclusions from an expanded series.

An ``EXDATE`` is a local wall time that should drop the matching occurrence
from the series. A user who excludes their 2021-03-15 09:00 standup expects
exactly that day's 09:00 occurrence gone and every other day untouched.
"""

from recurrence_models import Occurrence, RecurringEvent
from timezone_rules import STANDARD_OFFSET_HOURS, ExplicitDstZone, WallTime, wall_to_unix
from occurrence_expander import expand


def _exdate_instants(event: RecurringEvent) -> set[int]:
    """Absolute instants for the event's EXDATEs.

    Each EXDATE wall time is converted to an instant using the zone's standard
    offset so it can be compared against the occurrence instants.
    """

    out: set[int] = set()
    for ex in event.exdates:
        out.add(wall_to_unix(ex, STANDARD_OFFSET_HOURS))
    return out


def apply_exdates(zone: ExplicitDstZone, event: RecurringEvent) -> list[Occurrence]:
    """Expand the event and drop occurrences matching its EXDATEs."""

    series = expand(zone, event)
    if not event.exdates:
        return series

    excluded = _exdate_instants(event)
    kept: list[Occurrence] = []
    for occ in series:
        if occ.instant in excluded:
            continue
        kept.append(occ)
    return kept


def excluded_occurrences(zone: ExplicitDstZone, event: RecurringEvent) -> list[Occurrence]:
    """The occurrences that an EXDATE removed (for audit/debug views)."""

    full = expand(zone, event)
    kept = apply_exdates(zone, event)
    kept_keys = {(o.index, o.instant) for o in kept}
    return [o for o in full if (o.index, o.instant) not in kept_keys]


def is_excluded(zone: ExplicitDstZone, event: RecurringEvent, occ: Occurrence) -> bool:
    return occ.instant in _exdate_instants(event)


def exdate_count(event: RecurringEvent) -> int:
    return len(event.exdates)


def kept_count(zone: ExplicitDstZone, event: RecurringEvent) -> int:
    return len(apply_exdates(zone, event))


def kept_local_dates(
    zone: ExplicitDstZone, event: RecurringEvent
) -> list[tuple[int, int, int]]:
    return [o.date_tuple() for o in apply_exdates(zone, event)]


def kept_instants(zone: ExplicitDstZone, event: RecurringEvent) -> list[int]:
    return [o.instant for o in apply_exdates(zone, event)]


def matches_local_date(occ: Occurrence, target: WallTime) -> bool:
    """Whether an occurrence falls on the same local date as a target wall time."""

    return occ.date_tuple() == target.date_tuple()


def describe_exclusions(zone: ExplicitDstZone, event: RecurringEvent) -> dict[str, object]:
    removed = excluded_occurrences(zone, event)
    return {
        "event_id": event.event_id,
        "exdate_count": exdate_count(event),
        "removed_count": len(removed),
        "removed_dates": [o.date_tuple() for o in removed],
        "kept_count": kept_count(zone, event),
    }

