from __future__ import annotations

"""Expand a recurring event into concrete occurrences.

Starting from ``DTSTART`` resolved in the event's zone, walk forward one step
(a day for DAILY, a week for WEEKLY, times the interval) until the COUNT or
UNTIL bound is reached. Each occurrence carries both the absolute instant and
the local wall time the zone shows at that instant.
"""

from recurrence_models import Occurrence, RecurringEvent
from timezone_rules import ExplicitDstZone
from wall_clock import (
    add_absolute_days,
    instant_to_wall,
    resolve_wall_to_instant,
)

MAX_OCCURRENCES = 1000


def _start_instant(zone: ExplicitDstZone, event: RecurringEvent) -> int:
    return resolve_wall_to_instant(zone, event.dtstart)


def expand(zone: ExplicitDstZone, event: RecurringEvent) -> list[Occurrence]:
    """Return the ordered occurrences of an event in its zone.

    The walk keeps a running absolute instant for the current occurrence and
    advances it by the rule's step. Each step is a fixed span of real time so
    the series stays evenly spaced.
    """

    rule = event.rule
    step_days = rule.step_days()

    occurrences: list[Occurrence] = []
    instant = _start_instant(zone, event)
    index = 0

    while True:
        if rule.count is not None and index >= rule.count:
            break
        if rule.until_instant is not None and instant > rule.until_instant:
            break
        if index >= MAX_OCCURRENCES:
            break

        wall = instant_to_wall(zone, instant)
        occurrences.append(
            Occurrence(
                event_id=event.event_id,
                index=index,
                instant=instant,
                local_wall=wall,
            )
        )

        index += 1
        instant = add_absolute_days(instant, step_days)

    return occurrences


def expand_until_instant(
    zone: ExplicitDstZone,
    event: RecurringEvent,
    horizon_instant: int,
) -> list[Occurrence]:
    """Occurrences up to and including a horizon instant, regardless of rule bound."""

    return [o for o in expand(zone, event) if o.instant <= horizon_instant]


def occurrence_count(zone: ExplicitDstZone, event: RecurringEvent) -> int:
    return len(expand(zone, event))


def first_occurrence(zone: ExplicitDstZone, event: RecurringEvent) -> Occurrence | None:
    series = expand(zone, event)
    return series[0] if series else None


def last_occurrence(zone: ExplicitDstZone, event: RecurringEvent) -> Occurrence | None:
    series = expand(zone, event)
    return series[-1] if series else None


def local_clock_set(zone: ExplicitDstZone, event: RecurringEvent) -> set[tuple[int, int, int]]:
    """The distinct local clock readings across the whole series."""

    return {o.clock() for o in expand(zone, event)}


def instants(zone: ExplicitDstZone, event: RecurringEvent) -> list[int]:
    return [o.instant for o in expand(zone, event)]


def local_dates(zone: ExplicitDstZone, event: RecurringEvent) -> list[tuple[int, int, int]]:
    return [o.date_tuple() for o in expand(zone, event)]


def describe_series(zone: ExplicitDstZone, event: RecurringEvent) -> list[dict[str, object]]:
    rows = []
    for o in expand(zone, event):
        rows.append(
            {
                "index": o.index,
                "instant": o.instant,
                "wall": str(o.local_wall),
                "offset_hours": zone.offset_at_instant(o.instant),
            }
        )
    return rows

