from __future__ import annotations

"""Recurring-event model: a start, a repeat rule, and exclusions.

An event starts at a local wall-clock time in a named zone (``DTSTART`` with a
``TZID``). It repeats per an ``RRULE`` that supports ``FREQ=DAILY`` and
``FREQ=WEEKLY`` bounded by either ``COUNT`` (a number of occurrences) or
``UNTIL`` (an inclusive last instant). ``EXDATE`` lists local wall times that
should be removed from the expanded series.
"""

from dataclasses import dataclass, field

from timezone_rules import WallTime


@dataclass(frozen=True)
class RecurrenceRule:
    freq: str  # "DAILY" or "WEEKLY"
    interval: int = 1
    count: int | None = None
    until_instant: int | None = None

    def __post_init__(self) -> None:
        if self.freq not in {"DAILY", "WEEKLY"}:
            raise ValueError("freq must be DAILY or WEEKLY")
        if self.interval < 1:
            raise ValueError("interval must be at least 1")
        if self.count is not None and self.until_instant is not None:
            raise ValueError("set only one of count or until")
        if self.count is not None and self.count < 1:
            raise ValueError("count must be positive")

    def is_bounded(self) -> bool:
        return self.count is not None or self.until_instant is not None

    def step_days(self) -> int:
        return self.interval if self.freq == "DAILY" else self.interval * 7


@dataclass(frozen=True)
class RecurringEvent:
    event_id: str
    tzid: str
    dtstart: WallTime
    rule: RecurrenceRule
    summary: str = ""
    exdates: tuple[WallTime, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        if not self.event_id.strip():
            raise ValueError("event_id is required")
        if not self.tzid.strip():
            raise ValueError("tzid is required")

    def with_exdates(self, exdates: list[WallTime]) -> "RecurringEvent":
        return RecurringEvent(
            event_id=self.event_id,
            tzid=self.tzid,
            dtstart=self.dtstart,
            rule=self.rule,
            summary=self.summary,
            exdates=tuple(exdates),
        )


@dataclass(frozen=True)
class Occurrence:
    event_id: str
    index: int
    instant: int
    local_wall: WallTime

    def date_tuple(self) -> tuple[int, int, int]:
        return self.local_wall.date_tuple()

    def clock(self) -> tuple[int, int, int]:
        return (self.local_wall.hour, self.local_wall.minute, self.local_wall.second)


def _parse_wall(text: str) -> WallTime:
    """Parse a compact ``YYYYMMDDTHHMMSS`` local stamp."""

    text = text.strip()
    if "T" not in text:
        raise ValueError(f"bad wall stamp {text!r}")
    date_part, time_part = text.split("T", 1)
    if len(date_part) != 8 or len(time_part) < 4:
        raise ValueError(f"bad wall stamp {text!r}")
    year = int(date_part[0:4])
    month = int(date_part[4:6])
    day = int(date_part[6:8])
    hour = int(time_part[0:2])
    minute = int(time_part[2:4])
    second = int(time_part[4:6]) if len(time_part) >= 6 else 0
    return WallTime(year, month, day, hour, minute, second)


def parse_rrule(text: str, *, until_resolver=None) -> RecurrenceRule:
    """Parse an RRULE string such as ``FREQ=DAILY;COUNT=5``.

    ``until_resolver`` turns a parsed UNTIL wall time into an absolute instant
    (the caller supplies the zone). If absent, UNTIL is rejected.
    """

    parts: dict[str, str] = {}
    for chunk in text.split(";"):
        chunk = chunk.strip()
        if not chunk:
            continue
        key, _, value = chunk.partition("=")
        parts[key.strip().upper()] = value.strip()

    freq = parts.get("FREQ", "").upper()
    interval = int(parts.get("INTERVAL", "1"))
    count = int(parts["COUNT"]) if "COUNT" in parts else None
    until_instant = None
    if "UNTIL" in parts:
        if until_resolver is None:
            raise ValueError("UNTIL requires a zone resolver")
        until_instant = until_resolver(_parse_wall(parts["UNTIL"]))

    return RecurrenceRule(
        freq=freq,
        interval=interval,
        count=count,
        until_instant=until_instant,
    )


def parse_exdates(text: str) -> list[WallTime]:
    """Parse a comma-separated EXDATE list of local stamps."""

    if not text.strip():
        return []
    return [_parse_wall(piece) for piece in text.split(",") if piece.strip()]


def build_event(
    *,
    event_id: str,
    tzid: str,
    dtstart: WallTime,
    rule: RecurrenceRule,
