from __future__ import annotations

"""Wall-clock arithmetic and zone-aware conversion.

This sits between the raw zone (``timezone_rules``) and the expander. It offers
two distinct ways to think about advancing a recurring event:

* by *wall clock* — add N calendar days/weeks to the local date, keeping the
  same hour and minute on the wall, then resolve that wall time to an instant
  in the zone;
* by *absolute time* — add N * 24h (or N * 7 * 24h) of real seconds to an
  instant.

These agree for most of the year and disagree across a DST change. The
expander needs to pick the right one.
"""

from timezone_rules import (
    SECONDS_PER_DAY,
    ExplicitDstZone,
    WallTime,
    _civil_from_days,
    _days_from_civil,
    unix_to_wall,
    wall_to_unix,
)


def add_calendar_days(wall: WallTime, days: int) -> WallTime:
    """Add whole days to a wall time, keeping hour/minute/second fixed."""

    base = _days_from_civil(wall.year, wall.month, wall.day) + days
    year, month, day = _civil_from_days(base)
    return WallTime(year, month, day, wall.hour, wall.minute, wall.second)


def add_calendar_weeks(wall: WallTime, weeks: int) -> WallTime:
    return add_calendar_days(wall, weeks * 7)


def resolve_wall_to_instant(zone: ExplicitDstZone, wall: WallTime) -> int:
    """Resolve a local wall time to the matching absolute instant in the zone.

    Because the offset depends on the instant and the instant depends on the
    offset, this guesses with the standard offset, reads the offset the zone
    actually reports at that guess, and recomputes. Two passes converge for a
    single same-day transition.
    """

    from timezone_rules import STANDARD_OFFSET_HOURS

    guess = wall_to_unix(wall, STANDARD_OFFSET_HOURS)
    actual_offset = zone.offset_at_instant(guess)
    instant = wall_to_unix(wall, actual_offset)
    # Re-check: the corrected instant may land on the other side of a boundary.
    rechecked = zone.offset_at_instant(instant)
    if rechecked != actual_offset:
        instant = wall_to_unix(wall, rechecked)
    return instant


def instant_to_wall(zone: ExplicitDstZone, instant: int) -> WallTime:
    """Read the local wall time the zone shows at an absolute instant."""

    return unix_to_wall(instant, zone.offset_at_instant(instant))


def add_absolute_days(instant: int, days: int) -> int:
    """Advance an instant by a fixed number of 24-hour spans of real time."""

    return instant + days * SECONDS_PER_DAY


def add_absolute_weeks(instant: int, weeks: int) -> int:
    return add_absolute_days(instant, weeks * 7)


def same_local_clock(a: WallTime, b: WallTime) -> bool:
    """Whether two wall times read the same hour/minute/second."""

    return (a.hour, a.minute, a.second) == (b.hour, b.minute, b.second)


def same_local_date(a: WallTime, b: WallTime) -> bool:
    return a.date_tuple() == b.date_tuple()


def wall_clock_seconds(wall: WallTime) -> int:
    """Seconds-into-the-day for a wall time (0..86399)."""

    return wall.hour * 3600 + wall.minute * 60 + wall.second


def local_midnight(wall: WallTime) -> WallTime:
    return WallTime(wall.year, wall.month, wall.day, 0, 0, 0)


def describe_local(zone: ExplicitDstZone, instant: int) -> dict[str, object]:
    wall = instant_to_wall(zone, instant)
    return {
        "instant": instant,
        "offset_hours": zone.offset_at_instant(instant),
        "wall": str(wall),
        "clock_seconds": wall_clock_seconds(wall),
    }


def hours_between(a_instant: int, b_instant: int) -> float:
    return (b_instant - a_instant) / 3600.0

